def time_slide(int_time, minutes):
    m = (int_time % 100)
    int_time -= m
    m += minutes
    int_time += (m // 60 * 100 + m % 60)
    return (int_time % 2400)
def write_csv(fileName, fields, data, indexOrder=None, sortOrder=None):
    try:
        df_new = pd.DataFrame(data, columns=fields)
        useFileName = fileName.replace('.bak', '')
        if (not os.path.exists(useFileName)):
            if sortOrder:
                df_new.sort_values(sortOrder, inplace=True, ascending=False)
            df_new.to_csv(fileName, index=False, encoding='utf-8')
        else:
            if indexOrder:
                df = pd.read_csv(useFileName, encoding='utf-8', dtype=str)
                df = df_new.append(df)
                isdup = list(df.duplicated(indexOrder))
                if (True in isdup):
                    df = df.drop_duplicates(indexOrder)
            else:
                df = df_new
            if sortOrder:
                df.sort_values(sortOrder, inplace=True, ascending=False)
            df.to_csv(fileName, index=False, encoding='utf-8')
        os.system(f'mv {fileName!s} {useFileName!s}')
        return True
    except BaseException:
        system_log.error(get_traceback_message())
        return False
def lock_with(lock):
    def lock_mark(func):
        def locked_func(*args, **kwargs):
            try:
                lock.acquire()
                func(*args, **kwargs)
            except BaseException as e:
                system_log.error(get_traceback_message())
                raise e
            finally: lock.release()
        return locked_func
    return lock_mark
