def check_file_path_valid(save_path):
    if (len(save_path) > 256):
        msg = '传入路径非法，无法导出交易数据'
        return (False, msg)
    else:
        system = get_system()
        file_path_pattern = FILE_PATH_PATTERN_DICT.get(system)
        if (file_path_pattern is None):
            return (False, '未知系统标识:%s' % system)
        elif re.match(file_path_pattern, save_path):
            return (True, '')
        return (False, '传入的路径中包含非法字符，无法导出交易数据')
def check_datetime(c_date):
    if (c_date is None):
        return None
    else:
        assert (len(c_date) == 8 or len(c_date) == 10 or len(c_date) == 12 or len(c_date) == 16), "您输入的时间格式不正确，请使用正确的格式: 'YYYYmmdd'、'YYYY-mm-dd'、'YYYYmmddHHMM'或'YYYY-mm-dd HH:MM'"
        if (len(c_date) == 8):
            try:
                qdt.datetime.strptime(c_date, '%Y%m%d')
            except BaseException:
                system_log.error(get_traceback_message())
                assert False, "您输入的时间格式不正确，请使用正确格式：'YYYYmmdd'"
        elif (len(c_date) == 10):
            try:
                c_date = c_date.replace('-', '')
                qdt.datetime.strptime(c_date, '%Y%m%d')
            except BaseException:
                system_log.error(get_traceback_message())
                assert False, "您输入的时间格式不正确，请使用正确格式：'YYYY-mm-dd'"
        elif (len(c_date) == 12):
            try:
                qdt.datetime.strptime(c_date, '%Y%m%d%H%M')
            except BaseException:
                system_log.error(get_traceback_message())
                assert False, "您输入的时间格式不正确，请使用正确格式：'YYYYmmddHHMM'"
        elif (len(c_date) == 16):
            try:
                c_date = c_date.replace('-', '').replace(' ', '').replace(':', '')
                qdt.datetime.strptime(c_date, '%Y%m%d%H%M')
            except BaseException:
                system_log.error(get_traceback_message())
                assert False, "您输入的时间格式不正确，请使用正确格式：'YYYY-mm-dd HH:MM'"
        assert (1990 <= int(c_date[:4]) <= 9999), '您输入的年份格式不正确'
        return c_date
