def get_container_stats_info(user_id):
    result_data = {'data': {'cpu_per': [], 'mem_usage': [], 'mem_per': []}}
    cpu_per_value = '--%'
    mem_usage_value = '--M'
    mem_per_value = '--%'
    cid = get_cid_from_ciddict(user_id)
    if (cid == ''):
        result_data['data']['cpu_per'].append(cpu_per_value)
        result_data['data']['mem_usage'].append(mem_usage_value)
        result_data['data']['mem_per'].append(mem_per_value)
        return result_data
    else:
        mem_usage_data = get_usege_mem(cid)
        if (mem_usage_data > 0):
            mem_usage_data = float('%.2f' % mem_usage_data)
            mem_usage_value = ('%s' % str(mem_usage_data) + 'M')
        mem_max_data = get_max_mem(cid)
        if (mem_max_data > 0 and mem_usage_data > 0):
            usage_per = float('%.2f' % (mem_usage_data / mem_max_data * 100))
            mem_per_value = ('%s' % str(usage_per) + '%')
        result_data['data']['cpu_per'].append(cpu_per_value)
        result_data['data']['mem_usage'].append(mem_usage_value)
        result_data['data']['mem_per'].append(mem_per_value)
        return result_data
def whitelist_filter(code):
    recode = {'error_no': 0, 'error_list': []}
    code = code.split('\n')
    check_dict = {'pack_list': [], 'cmd_list': [], 'func_list': []}
    if (pack_filter_mode == 1):
        if (len(white_pack_list) > 0 and white_pack_list != ''):
            check_dict['pack_list'] = white_pack_list
    elif (pack_filter_mode == 2):
        if (len(black_pack_list) > 0 and black_pack_list != ''):
            check_dict['pack_list'] = black_pack_list
    if (len(black_func_list) > 0 and black_func_list != ''):
        check_dict['func_list'] = black_func_list
    if (cmd_filter_mode == 1):
        if (len(white_cmd_list) > 0 and white_cmd_list != ''):
            check_dict['cmd_list'] = white_cmd_list
    elif (cmd_filter_mode == 2):
        if (len(black_cmd_list) > 0 and black_cmd_list != ''):
            check_dict['cmd_list'] = black_cmd_list
    recode = process_filter(code, check_dict, pack_filter_mode, cmd_filter_mode)
    return recode
def process_filter(code, check_dict, pack_mode, cmd_mode):
    tmplist = []
    pl = check_dict['pack_list']
    cl = check_dict['cmd_list']
    fl = check_dict['func_list']
    three_double_quotes_start = False
    def remove_blank(strcontext):
        if isinstance(strcontext, list):
            strcontext = '\n'.join(strcontext)
        return strcontext.lstrip().rstrip()
    def re_start_with_context(strstart, strcontext):
        strcontext = remove_blank(strcontext)
        return re.compile('^' + strstart + '\\W').search(strcontext)
    def re_start_with_hash(strcontext):
        strcontext = remove_blank(strcontext)
        return re.compile('^#').search(strcontext)
    def re_include_context(strsearch, strcontext):
        strcontext = remove_blank(strcontext)
        return re.compile('\\W' + strsearch + '(\\W|$)').search(strcontext)
    def re_start_with_exelmark(strcontext):
        strcontext = remove_blank(strcontext)
        return re.compile('^!').search(strcontext)
    def re_include_three_double_quotes(strcontext):
        strcontext = remove_blank(strcontext)
        return re.compile('"""').search(strcontext)
    def re_contain_context(strsearch, strcontext):
        pattern = ('(?<![.\\w])\\s*(?:=)?\\s*' + re.escape(strsearch) + '\\b')
        return re.findall(pattern, strcontext)
    def re_include_cmd(str_search, str_context):
        str_context = str_context.lstrip()
        if str_context.startswith('!'):
            str_context = str_context[1:]
        return re.search('^%s(?:\\s|$)' % str_search, str_context)
    if (pack_mode != 0 or cmd_mode != 0):
        for line in code:
            if re_include_three_double_quotes(line):
                three_double_quotes_start = (not three_double_quotes_start)
                continue
            elif three_double_quotes_start:
                continue
            elif re_start_with_hash(line):
                continue
            elif re_start_with_context('print', line):
                continue
            elif re_start_with_context('log.info', line):
                continue
            elif (re_start_with_context('from', line) or re_start_with_context('import', line)):
                if (pack_mode == 1):
                    packs = line.split(' ')
                    if (len(packs) > 1 and packs[1] != ''):
                        pack = packs[1]
                        if (pack not in pl):
                            tmplist.append(pack)
                elif (pack_mode == 2):
                    for pack in pl:
                        if re_include_context(pack, line):
                            tmplist.append(pack)
                        continue
            elif re_start_with_exelmark(line):
                if (cmd_mode == 1):
                    line_cmd = line.replace('!', '')
                    splits = line_cmd.split(' ')
                    if (len(splits) > 0):
                        cmd = splits[0]
                    else:
                        cmd = splits
                    if (cmd not in cl):
                        tmplist.append(cmd)
                elif (cmd_mode == 2):
                    for cmd in cl:
                        if re_include_context(cmd, line):
                            tmplist.append(cmd)
                        continue
            if (pack_mode != 0):
                for func in fl:
                    if re_contain_context(func, line):
                        tmplist.append(func)
                        continue
                    elif ('.' in func):
                        pack = func.split('.')[0]
                        method = func.split('.')[-1]
                        if re_start_with_context('from', line):
                            if (re_include_context(pack, line) and re_include_context(method, code)):
                                tmplist.append(func)
                            continue
                        elif (re_start_with_context('import', line) and re_include_context(pack, line) and re_include_context(method, code)):
                            tmplist.append(func)
    if (len(tmplist) > 0):
        tmplist = list(set(tmplist))
        return {'error_no': -1, 'error_list': tmplist}
    else:
        return {'error_no': 0, 'error_list': tmplist}
