@unique
class ProcessWrite(object):
    def __init__(self):
        self.thread_end = False
        self.default = object()
    def start_write_file_thread(self, user_id, filepath, filename, mode, paramsdict, dataQueue):
        func_name = None
        if (mode == 0):
            func_name = self.write_backtest_info
        if func_name:
            _create_thread = Thread(target=func_name, args=(user_id, filepath, filename, paramsdict, dataQueue))
            _create_thread.setDaemon(True)
            _create_thread.start()
        return _create_thread
    def write_backtest_info(self, user_id, filepath, filename, paramsdict, dataQueue):
        file_path_name = self.create_file_path(filepath, filename)
        backtestid = paramsdict.get('backtest_id', None)
        log = paramsdict.get('log', None)
        backtestmode = paramsdict.get('mode', None)
        while True:
            try:
                datadict = dataQueue.get(timeout=5)
                if (datadict == self.default):
                    break
                else:
                    self.modify_batcktes_info(user_id, filename, backtestid, log, backtestmode, file_path_name, datadict)
            except Empty: pass
            except BaseException as ex:
                if log:
                    if (backtestmode == 'backtest'):
                        log.backtest.info(ex)
                    elif (backtestmode == 'trade'):
                        log.trade_norm.info(ex)
                if self.thread_end:
                    break
                continue
