def check_stock_or_future(stocks):
    if isinstance(stocks, str):
        if (stocks.find('SS') > -1 or stocks.find('SZ') > -1 or stocks.find('XSHE') > -1 or stocks.find('XSHG') > -1):
            return 'stock'
        elif (stocks.find('CCFX') > -1 or stocks.find('XDCE') > -1 or stocks.find('XSGE') > -1 or stocks.find('XZCE') > -1):
            return 'future'
        return 'other'
    elif isinstance(stocks, list):
        stock_flag = 0
        future_flag = 0
        for stock_code in stocks:
            if (stock_code.find('SS') > -1 or stock_code.find('SZ') > -1 or stock_code.find('XSHE') > -1 or stock_code.find('XSHG') > -1):
                stock_flag = 1
            if (stock_code.find('CCFX') > -1 or stock_code.find('XDCE') > -1 or not stock_code.find('XSGE') > -1):
                if (stock_code.find('XZCE') > -1):
                    future_flag = 1
                continue
        return 'stock'
        if (stock_flag == 0 and future_flag == 1):
            return 'future'
        else:
            return 'other'
@unique
class FileLockException(Exception):
    pass
@unique
class FileLock(object):
    __doc__ = " A file locking mechanism that has context-manager support so\n        you can use it in a with statement. This should be relatively cross\n        compatible as it doesn't rely on msvcrt or fcntl for the locking.\n    "
    def __init__(self, user_id, file_name, file_path=None, timeout=10, delay=0.05):
        self.is_locked = False
        if file_path:
            self.lockfile = file_path
        else:
            self.lockfile = os.path.join('/dev/shm/', f'{user_id!s}.{file_name!s}.lock')
        self.file_name = file_name
        self.timeout = timeout
        self.delay = delay
    def acquire(self):
        start_time = time.time()
        try:
            pass
        except OSError as e:
            if (e.errno != errno.EEXIST):
                if os.path.exists(self.lockfile):
                    os.unlink(self.lockfile)
                else:
                    raise
            elif (time.time() - start_time >= self.timeout):
                os.unlink(self.lockfile)
                raise FileLockException('Timeout occured.')
            else:
                time.sleep(self.delay)
        else:
            self.is_locked = True
            return None
        break
    def release(self):
        if self.is_locked:
            os.close(self.fd)
            os.unlink(self.lockfile)
            self.is_locked = False
            return None
    def __enter__(self):
        if (not self.is_locked):
            self.acquire()
        return self
    def __exit__(self, type, value, traceback):
        if self.is_locked:
            self.release()
            return None
    def __del__(self):
        if self.is_locked:
            self.release()
            return None
def get_mem_under_oom_status(username):
    recode = {'error_no': 0, 'error_info': ''}
    cid = get_cid_from_ciddict(username)
    if (cid == ''):
        return recode
    else:
        contextlist = get_cgroup_info(cid, CG_TYPE[7], MEM_FILE[3])
        for under_oom in contextlist:
            if ('under_oom 1' in under_oom):
                recode['error_no'] = 1
                recode['error_info'] = '内存超过上限'
                break
        return recode
def kill_backtest_proc(username):
    cid = get_cid_from_ciddict(username)
    if (cid == ''):
        return None
    else:
        contextlist = get_cgroup_info(cid, CG_TYPE[7], MEM_FILE[26])
        contextlist.reverse()
        for procno in contextlist:
            with os.popen('ps -ef | grep %s' % procno) as output:
                context = output.readline()
                while context != '':
                    if ('/runtime/kernel-' in context and 'ipykernel' in context and 'python3.5' in context):
                        os.kill(int(procno), 9)
                        break
                    context = output.readline()
