def check_docker_status_new(user_id):
    try:
        status = ('running' in os.popen("docker inspect jupyter-%s |grep 'Status'" % user_id).read())
    except TimeoutError:
        from tornado.log import app_log
        app_log.error('获取容器状态超时')
        status = False
    return status
